import React, { useState, useEffect } from 'react';
import { Link, useLocation } from 'react-router-dom';

const Navbar = () => {
  const [scrolled, setScrolled] = useState(false);
  const location = useLocation();
  const isHomePage = location.pathname === "/";

  useEffect(() => {
    const handleScroll = () => {
      setScrolled(window.scrollY > 20);
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const navBgColor = (!isHomePage || scrolled) ? 'bg-[#064e3b] shadow-2xl py-4' : 'bg-transparent py-6';
  const textColor = 'text-white'; 

  return (
    <nav className={`fixed top-0 w-full z-50 transition-all duration-500 ${navBgColor}`}>
      <div className="max-w-7xl mx-auto px-6 flex justify-between items-center">

        {/* Logo & Headline */}
        <Link to="/" className="flex items-center gap-4 group">
          <div className="w-16 h-16 overflow-hidden rounded-xl bg-transparent flex items-center justify-center">
             <img 
               src="https://img.freepik.com/premium-vector/lawbridge-logo-lawyer-icon-legal-bridge-symbol_102100-244.jpg" 
               alt="LawBridge Logo" 
               className="w-full h-full object-contain"
             />
          </div>
          <div className="flex flex-col border-l-2 border-emerald-400/30 pl-4">
            <span className="text-2xl font-extrabold font-poppins tracking-tight text-white leading-tight">
              LawBridge
            </span>
            <span className="text-[10px] uppercase tracking-[0.2em] text-emerald-400 font-black">
              Bridging Clients & Lawyers
            </span>
          </div>
        </Link>

        {/* Links */}
        <div className="hidden md:flex space-x-10 items-center">
          <Link to="/" className="text-white hover:text-emerald-400 font-semibold transition-colors">Home</Link>
          <Link to="/lawyers" className="text-white hover:text-emerald-400 font-semibold transition-colors">Lawyers</Link>
          <Link to="/documents" className="text-white hover:text-emerald-400 font-semibold transition-colors">Documents</Link>
          <Link to="/contact" className="text-white hover:text-emerald-400 font-semibold transition-colors">Contact</Link>

          <Link to="/signup" className="bg-emerald-400 hover:bg-white text-emerald-950 px-8 py-3 rounded-xl font-bold transition-all shadow-lg active:scale-95">
            Get Started
          </Link>
        </div>
      </div>
    </nav>
  );
};

export default Navbar;
